// =====================================================================
// 4.03 - Calcula Report (Inbound e Remarketing separados)
//
// FONTE UNICA: sdr_eventos (Supabase) para disparos/respostas/falhas
//              + node "agenda" (MySQL) para calls.
// Nao usa mais a planilha "mailing" nem as materialized views
// (mv_sdr_disparos_diario / mv_sdr_respostas_diario), que nao sao
// refreshadas por nenhum fluxo.
//
// CANAL = nome_app do proprio evento (SDR-INBOUND / SDR-REMARKETING).
// Disparos, respostas e encaminhamentos ja nascem carimbados pelos fluxos,
// entao aqui nao ha inferencia: le-se a coluna. O canal e do EVENTO, nao do
// lead - lead de inbound que entrou na regua de remarketing (o FUP) conta
// como remarketing a partir do momento em que o 6.01 dispara para ele.
//
// Calls sao a excecao: vem do MySQL, que nao tem nome_app. A atribuicao usa,
// nesta ordem: (1) origem da reuniao em sdr_reunioes, que os calendars
// carimbam; (2) nome_app do ultimo disparo ANTES daquele dia; (3) mailing.midia.
//
// FUSO: tudo convertido para America/Sao_Paulo (UTC-3, sem horario de
// verao). "Ontem" = dia civil brasileiro, nao janela UTC.
// SEMANA VIGENTE = domingo desta semana ate ontem (D-1).
// =====================================================================

const OFFSET_MIN = -180;              // America/Sao_Paulo
const DIA_MS = 86400000;

function diaLocal(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d)) return null;
  const l = new Date(d.getTime() + OFFSET_MIN * 60000);
  return Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate());
}
function tsLocal(iso) {
  const d = new Date(iso);
  return isNaN(d) ? null : d.getTime();
}

const agoraLocal = new Date(Date.now() + OFFSET_MIN * 60000);
const HOJE = Date.UTC(agoraLocal.getUTCFullYear(), agoraLocal.getUTCMonth(), agoraLocal.getUTCDate());
const ONTEM = HOJE - DIA_MS;
const INICIO_SEMANA = HOJE - new Date(HOJE).getUTCDay() * DIA_MS;

function ehOntem(t) { return t === ONTEM; }
function ehSemana(t) { return t !== null && t >= INICIO_SEMANA && t < HOJE; }
function ddmm(t) {
  const d = new Date(t);
  return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0');
}
// Taxa so existe se houve disparo no periodo. Sem denominador a taxa nao e
// zero - ela nao se aplica, e mostrar "0.0%" faz parecer que o disparo
// nao converteu, quando na verdade nao houve disparo.
function taxa(num, den) {
  return den > 0 ? `taxa ${(num / den * 100).toFixed(1)}%` : 'sem disparos no período';
}

// ---------------------------------------------------------------------
// 1. Eventos
// ---------------------------------------------------------------------
const eventos = $('Eventos SDR - Ler').all().map(i => i.json);

function parsePayload(p) {
  try { return typeof p === 'string' ? JSON.parse(p) : (p || {}); } catch (e) { return {}; }
}
// tipo_disparo e coluna dedicada (preenchida pelos fluxos 6.01 e 7.01);
// payload.template fica como fallback para eventos antigos.
function templateDoEvento(e) {
  return e.tipo_disparo || parsePayload(e.payload).template || null;
}
function canalPorApp(app) {
  const a = String(app || '').toUpperCase();
  if (a.indexOf('INBOUND') >= 0) return 'inbound';
  if (a.indexOf('REMARKETING') >= 0) return 'remarketing';
  if (a.indexOf('OUTBOUND') >= 0) return 'outbound';
  return null;
}
function canalPorTemplate(tpl) {
  const t = String(tpl || '');
  if (t.indexOf('inbound') >= 0) return 'inbound';
  if (t.indexOf('outbound') >= 0) return 'outbound';
  if (/^mensagem_\d+/.test(t)) return 'remarketing';
  return null;
}
// Tentativa dentro da regua de remarketing (1, 2 ou 3). Disparo inicial
// de inbound/outbound nao tem regua -> 'inicial'.
function tentativaDoTemplate(tpl) {
  const t = String(tpl || '');
  if (/disparo_inicial/.test(t)) return 'inicial';
  const m = t.match(/mensagem_(\d+)/);
  return m ? m[1] : null;
}
// Chave do lead: mailing_id quando existe, senao os ultimos 11 digitos do
// telefone. Sem isso, todo evento sem mailing_id colapsava num unico
// balde (bug do report antigo).
function chaveLead(e) {
  if (e.mailing_id !== null && e.mailing_id !== undefined && e.mailing_id !== '') return 'm' + e.mailing_id;
  const tel = String(e.telefone || '').replace(/\D/g, '');
  return tel ? 't' + tel.slice(-11) : null;
}

const CANAIS = ['inbound', 'remarketing', 'outbound', 'parcerias', 'outros'];
function novoBalde() {
  return {
    disparos_ontem: 0, disparos_semana: 0,
    disparos_ontem_t: { inicial: 0, '1': 0, '2': 0, '3': 0 },
    disparos_semana_t: { inicial: 0, '1': 0, '2': 0, '3': 0 },
    falhas_ontem: 0, falhas_semana: 0,
    respostas_ontem: 0, respostas_semana: 0,
    respostas_ontem_t: { inicial: 0, '1': 0, '2': 0, '3': 0, sem_disparo: 0 },
    respostas_semana_t: { inicial: 0, '1': 0, '2': 0, '3': 0, sem_disparo: 0 },
    enc_advisor_ontem: 0, enc_advisor_semana: 0,
    enc_parcerias_ontem: 0, enc_parcerias_semana: 0,
    calls_marcadas_ontem: 0, calls_marcadas_semana: 0,
    calls_realizadas_ontem: 0, calls_realizadas_semana: 0,
    calls_noshow_ontem: 0, calls_noshow_semana: 0,
    calls_hoje: 0, calls_a_frente: 0
  };
}
const R = {};
for (const c of CANAIS) R[c] = novoBalde();

// ---------------------------------------------------------------------
// 2. Historico de disparos por lead (canal + tentativa + data)
// ---------------------------------------------------------------------
const historico = {};   // chaveLead -> [{ts, canal, tentativa}]
for (const e of eventos) {
  if (e.tipo_evento !== 'disparo_enviado') continue;
  const k = chaveLead(e);
  const ts = tsLocal(e.created_at);
  if (!k || ts === null) continue;
  const tpl = templateDoEvento(e);
  const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
  (historico[k] = historico[k] || []).push({ ts, canal, tentativa: tentativaDoTemplate(tpl) });
}
for (const k in historico) historico[k].sort((a, b) => a.ts - b.ts);

// Canal do lead num INSTANTE: o ultimo disparo ate aquela data. Usar o
// "ultimo disparo de todos" jogaria para remarketing uma call que nasceu da
// conversa de inbound semanas antes de o lead entrar no FUP.
function canalDoLeadEm(k, ts) {
  const h = historico[k];
  if (!h || !h.length) return null;
  let canal = null;
  for (const d of h) { if (d.ts <= ts) canal = d.canal; else break; }
  return canal || h[0].canal;
}
function canalDoLead(k) {
  const h = historico[k];
  return h && h.length ? h[h.length - 1].canal : null;
}
// Ultimo disparo ANTES da resposta. Janela de 7 dias para atribuir a
// tentativa: resposta a um disparo de 3 meses atras nao e resposta
// daquele disparo (o report antigo atribuia sem limite nenhum).
const JANELA_ATRIB_MS = 7 * DIA_MS;
function disparoAnterior(k, ts) {
  const h = historico[k];
  if (!h) return null;
  let achado = null;
  for (const d of h) { if (d.ts <= ts) achado = d; else break; }
  if (!achado) return null;
  return { canal: achado.canal, tentativa: (ts - achado.ts) <= JANELA_ATRIB_MS ? achado.tentativa : null };
}

// ---------------------------------------------------------------------
// 3. Disparos, falhas, respostas e encaminhamentos
// ---------------------------------------------------------------------
const vistoRespOntem = new Set();
const vistoRespSemana = new Set();

for (const e of eventos) {
  const dia = diaLocal(e.created_at);
  if (dia === null) continue;
  const ontem = ehOntem(dia);
  const semana = ehSemana(dia);
  if (!ontem && !semana) continue;

  const k = chaveLead(e);
  const tipo = String(e.tipo_evento || '');

  if (tipo === 'disparo_enviado') {
    const tpl = templateDoEvento(e);
    const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
    const t = tentativaDoTemplate(tpl);
    const b = R[canal] || R.outros;
    if (ontem) { b.disparos_ontem++; if (t) b.disparos_ontem_t[t] = (b.disparos_ontem_t[t] || 0) + 1; }
    if (semana) { b.disparos_semana++; if (t) b.disparos_semana_t[t] = (b.disparos_semana_t[t] || 0) + 1; }

  } else if (tipo === 'disparo_falhou') {
    const tpl = templateDoEvento(e);
    const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
    const b = R[canal] || R.outros;
    if (ontem) b.falhas_ontem++;
    if (semana) b.falhas_semana++;

  } else if (tipo === 'resposta_recebida') {
    const ts = tsLocal(e.created_at);
    const ant = k ? disparoAnterior(k, ts) : null;
    // O nome_app da resposta vem do historico de mensagens (trigger
    // fn_sdr_detecta_resposta) = o agente que recebeu. E a fonte certa.
    const canal = canalPorApp(e.nome_app) || (ant && ant.canal) || 'outros';
    const tent = ant && ant.tentativa ? ant.tentativa : 'sem_disparo';
    const b = R[canal] || R.outros;
    // dedupe: mesmo lead, mesmo dia = 1 resposta
    const chave = (k || 'evt' + e.id) + '_' + dia;
    if (ontem && !vistoRespOntem.has(chave)) {
      vistoRespOntem.add(chave);
      b.respostas_ontem++;
      b.respostas_ontem_t[tent] = (b.respostas_ontem_t[tent] || 0) + 1;
    }
    if (semana && !vistoRespSemana.has(chave)) {
      vistoRespSemana.add(chave);
      b.respostas_semana++;
      b.respostas_semana_t[tent] = (b.respostas_semana_t[tent] || 0) + 1;
    }

  } else if (/encaminh/i.test(tipo)) {
    // Eventos 'encaminhado_advisor' / 'encaminhado_parcerias', gravados pela
    // 6.04 (remarketing) e 7.04 (inbound), ja com nome_app fixo do fluxo.
    const p = parsePayload(e.payload);
    const destinoRaw = String(p.destino || tipo).toLowerCase();
    const destino = /parceri/.test(destinoRaw) ? 'parcerias' : (/advisor/.test(destinoRaw) ? 'advisor' : null);
    if (!destino) continue;
    const canal = canalPorApp(e.nome_app) || (k && canalDoLead(k)) || 'outros';
    const b = R[canal] || R.outros;
    const campo = destino === 'advisor' ? 'enc_advisor' : 'enc_parcerias';
    if (ontem) b[campo + '_ontem']++;
    if (semana) b[campo + '_semana']++;
  }
}

// ---------------------------------------------------------------------
// 4. Calls (node "agenda", linha a linha) atribuidas ao canal de ORIGEM
// ---------------------------------------------------------------------
const MIDIA_CANAL = { '14': 'inbound', '15': 'remarketing', '5': 'remarketing', '2': 'parcerias', '1': 'outbound', '4': 'outbound' };

// --- Reunioes carimbadas pelos calendars (sdr_reunioes.origem) ---
// Fonte mais confiavel de canal para uma call: quem agendou disse quem era.
// So cobre o que a IA agendou; call marcada na mao no CRM cai nos fallbacks.
const reunioesPorLead = {};
for (const r of $('Reunioes SDR - Ler').all().map(i => i.json)) {
  const canal = canalPorApp(r.origem);
  if (!canal) continue;
  const chaves = [];
  if (r.mailing_id) chaves.push('m' + r.mailing_id);
  const tel = String(r.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  const marcos = [tsLocal(r.criado_em), tsLocal(r.data_hora_agendada)].filter(t => t !== null);
  for (const c of chaves) (reunioesPorLead[c] = reunioesPorLead[c] || []).push({ canal, marcos });
}
function canalPorReuniao(chaves, ts) {
  let melhor = null, menorDist = Infinity;
  for (const c of chaves) {
    for (const r of (reunioesPorLead[c] || [])) {
      for (const m of r.marcos) {
        const dist = Math.abs(m - ts);
        if (dist < menorDist) { menorDist = dist; melhor = r.canal; }
      }
    }
  }
  return melhor;
}

function canalDaCall(row, ts) {
  const chaves = [];
  if (row.mailing_id !== null && row.mailing_id !== undefined && row.mailing_id !== '') chaves.push('m' + row.mailing_id);
  const tel = String(row.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  return canalPorReuniao(chaves, ts)
      || (chaves.length ? canalDoLeadEm(chaves[0], ts) : null)
      || MIDIA_CANAL[String(row.midia)]
      || 'outros';
}

const linhasAgenda = $('agenda1').all().map(i => i.json).filter(r => r && r.evento);
for (const row of linhasAgenda) {
  const dia = row.dia ? diaLocal(String(row.dia).slice(0, 10) + 'T12:00:00Z') : null;
  const b = R[canalDaCall(row, dia !== null ? dia : Date.now())] || R.outros;
  const ontem = dia !== null && ehOntem(dia);
  const semana = dia !== null && ehSemana(dia);
  switch (row.evento) {
    case 'marcada':
      if (ontem) b.calls_marcadas_ontem++;
      if (semana) b.calls_marcadas_semana++;
      break;
    case 'realizada':
      if (ontem) b.calls_realizadas_ontem++;
      if (semana) b.calls_realizadas_semana++;
      break;
    case 'no_show':
      if (ontem) b.calls_noshow_ontem++;
      if (semana) b.calls_noshow_semana++;
      break;
    case 'agendada_hoje': b.calls_hoje++; break;
    case 'agendada_frente': b.calls_a_frente++; break;
  }
}

// ---------------------------------------------------------------------
// 5. Montagem das mensagens
// ---------------------------------------------------------------------
const periodo = `Ontem ${ddmm(ONTEM)} · semana ${ddmm(INICIO_SEMANA)} → ${ddmm(ONTEM)}`;

// A soma das tentativas tem que fechar com o total. Disparo antigo, sem
// tipo_disparo e sem template no payload, nao cai em nenhuma tentativa -
// em vez de sumir da conta, aparece como "sem template".
// A soma das etapas tem que fechar com o total. "entrada" e o primeiro
// contato da regua (template disparo_inicial_*, disparado pela fila de
// entrada do 6.01) - nao e 1a/2a/3a tentativa. Se ainda sobrar diferenca,
// e disparo sem template identificavel e aparece como tal, em vez de sumir.
function entradaLbl(t) {
  return (t.inicial || 0) > 0 ? `entrada: ${t.inicial} | ` : '';
}
function restoDisp(total, t) {
  const resto = total - ((t['1'] || 0) + (t['2'] || 0) + (t['3'] || 0) + (t.inicial || 0));
  return resto > 0 ? ` | sem template: ${resto}` : '';
}

function blocoEncaminhamentos(b) {
  return `➡️ *ENCAMINHAMENTOS*
Advisor — ontem: ${b.enc_advisor_ontem} | semana: ${b.enc_advisor_semana}
Parcerias — ontem: ${b.enc_parcerias_ontem} | semana: ${b.enc_parcerias_semana}`;
}
function blocoCalls(b) {
  return `📅 *CALLS*
Agendadas — ontem: ${b.calls_marcadas_ontem} | semana: ${b.calls_marcadas_semana}
Realizadas — ontem: ${b.calls_realizadas_ontem} | semana: ${b.calls_realizadas_semana}
No-show — ontem: ${b.calls_noshow_ontem} | semana: ${b.calls_noshow_semana}
Na agenda — hoje: ${b.calls_hoje} | daqui pra frente: ${b.calls_a_frente}`;
}

// ---- INBOUND ----
const i = R.inbound;
const mensagem_inbound = `*REPORT INBOUND*
_${periodo}_

📤 *DISPAROS*
Ontem: ${i.disparos_ontem}${i.falhas_ontem ? ` (falhas: ${i.falhas_ontem})` : ''}
Semana: ${i.disparos_semana}${i.falhas_semana ? ` (falhas: ${i.falhas_semana})` : ''}

💬 *RESPOSTAS* (leads distintos que responderam)
Ontem: ${i.respostas_ontem} — ${taxa(i.respostas_ontem, i.disparos_ontem)}
Semana: ${i.respostas_semana} — ${taxa(i.respostas_semana, i.disparos_semana)}

${blocoEncaminhamentos(i)}

${blocoCalls(i)}`;

// ---- REMARKETING ----
const r = R.remarketing;
const dOnt = r.disparos_ontem_t, dSem = r.disparos_semana_t;
const rOnt = r.respostas_ontem_t, rSem = r.respostas_semana_t;
const o = R.outbound, p = R.parcerias, x = R.outros;
const outrosDispOntem = o.disparos_ontem + p.disparos_ontem + x.disparos_ontem;
const outrosDispSemana = o.disparos_semana + p.disparos_semana + x.disparos_semana;
const totalDispOntem = i.disparos_ontem + r.disparos_ontem + outrosDispOntem;
const totalDispSemana = i.disparos_semana + r.disparos_semana + outrosDispSemana;
const totalRespOntem = CANAIS.reduce((s, c) => s + R[c].respostas_ontem, 0);
const totalRespSemana = CANAIS.reduce((s, c) => s + R[c].respostas_semana, 0);

const mensagem_remarketing = `*REPORT REMARKETING*
_${periodo}_

📤 *DISPAROS*
Ontem: ${r.disparos_ontem}${r.falhas_ontem ? ` (falhas: ${r.falhas_ontem})` : ''}
• ${entradaLbl(dOnt)}1ª: ${dOnt['1']} | 2ª: ${dOnt['2']} | 3ª: ${dOnt['3']}${restoDisp(r.disparos_ontem, dOnt)}
Semana: ${r.disparos_semana}${r.falhas_semana ? ` (falhas: ${r.falhas_semana})` : ''}
• ${entradaLbl(dSem)}1ª: ${dSem['1']} | 2ª: ${dSem['2']} | 3ª: ${dSem['3']}${restoDisp(r.disparos_semana, dSem)}

💬 *RESPOSTAS* (leads distintos que responderam)
Ontem: ${r.respostas_ontem} — ${taxa(r.respostas_ontem, r.disparos_ontem)}
• ${entradaLbl(rOnt)}1ª: ${rOnt['1']} | 2ª: ${rOnt['2']} | 3ª: ${rOnt['3']} | sem disparo recente: ${rOnt.sem_disparo}
Semana: ${r.respostas_semana} — ${taxa(r.respostas_semana, r.disparos_semana)}
• ${entradaLbl(rSem)}1ª: ${rSem['1']} | 2ª: ${rSem['2']} | 3ª: ${rSem['3']} | sem disparo recente: ${rSem.sem_disparo}

${blocoEncaminhamentos(r)}

${blocoCalls(r)}

—
*TOTAL DA OPERAÇÃO (todos os canais)*
Disparos — ontem: ${totalDispOntem} | semana: ${totalDispSemana}
Respostas — ontem: ${totalRespOntem} | semana: ${totalRespSemana}
Outros canais (outbound/parcerias) — disparos ontem: ${outrosDispOntem} | semana: ${outrosDispSemana}
Respostas sem canal identificado — ontem: ${x.respostas_ontem} | semana: ${x.respostas_semana}
Calls agendadas ontem — inbound: ${i.calls_marcadas_ontem} | remarketing: ${r.calls_marcadas_ontem} | parcerias: ${p.calls_marcadas_ontem} | outros: ${o.calls_marcadas_ontem + x.calls_marcadas_ontem}`;

return [{
  json: {
    referencia_ontem: ddmm(ONTEM),
    inicio_semana: ddmm(INICIO_SEMANA),
    mensagem_inbound,
    mensagem_remarketing,
    detalhe: R
  }
}];

// =====================================================================
// 4.03 - Calcula Report (Inbound e Remarketing separados)
//
// FONTE UNICA: sdr_eventos (Supabase) para disparos/respostas/falhas
//              + node "agenda" (MySQL) para calls.
// Nao usa mais a planilha "mailing" nem as materialized views
// (mv_sdr_disparos_diario / mv_sdr_respostas_diario), que nao sao
// refreshadas por nenhum fluxo.
//
// CANAL = nome_app do proprio evento (SDR-INBOUND / SDR-REMARKETING).
// Disparos, respostas e encaminhamentos ja nascem carimbados pelos fluxos,
// entao aqui nao ha inferencia: le-se a coluna. O canal e do EVENTO, nao do
// lead - lead de inbound que entrou na regua de remarketing (o FUP) conta
// como remarketing a partir do momento em que o 6.01 dispara para ele.
//
// Calls sao a excecao: vem do MySQL, que nao tem nome_app. A atribuicao usa,
// nesta ordem: (1) origem da reuniao em sdr_reunioes, que os calendars
// carimbam; (2) nome_app do ultimo disparo ANTES daquele dia; (3) mailing.midia.
//
// FUSO: tudo convertido para America/Sao_Paulo (UTC-3, sem horario de
// verao). "Ontem" = dia civil brasileiro, nao janela UTC.
// SEMANA VIGENTE = domingo desta semana ate ontem (D-1).
// =====================================================================

const OFFSET_MIN = -180;              // America/Sao_Paulo
const DIA_MS = 86400000;

function diaLocal(iso) {
  if (!iso) return null;
  const d = new Date(iso);
  if (isNaN(d)) return null;
  const l = new Date(d.getTime() + OFFSET_MIN * 60000);
  return Date.UTC(l.getUTCFullYear(), l.getUTCMonth(), l.getUTCDate());
}
function tsLocal(iso) {
  const d = new Date(iso);
  return isNaN(d) ? null : d.getTime();
}

const agoraLocal = new Date(Date.now() + OFFSET_MIN * 60000);
const HOJE = Date.UTC(agoraLocal.getUTCFullYear(), agoraLocal.getUTCMonth(), agoraLocal.getUTCDate());
const ONTEM = HOJE - DIA_MS;
const INICIO_SEMANA = HOJE - new Date(HOJE).getUTCDay() * DIA_MS;

function ehOntem(t) { return t === ONTEM; }
function ehSemana(t) { return t !== null && t >= INICIO_SEMANA && t < HOJE; }
function ddmm(t) {
  const d = new Date(t);
  return String(d.getUTCDate()).padStart(2, '0') + '/' + String(d.getUTCMonth() + 1).padStart(2, '0');
}
// Taxa so existe se houve disparo no periodo. Sem denominador a taxa nao e
// zero - ela nao se aplica, e mostrar "0.0%" faz parecer que o disparo
// nao converteu, quando na verdade nao houve disparo.
function taxa(num, den) {
  return den > 0 ? `taxa ${(num / den * 100).toFixed(1)}%` : 'sem disparos no período';
}

// ---------------------------------------------------------------------
// 1. Eventos
// ---------------------------------------------------------------------
const eventos = $('Eventos SDR - Ler').all().map(i => i.json);

function parsePayload(p) {
  try { return typeof p === 'string' ? JSON.parse(p) : (p || {}); } catch (e) { return {}; }
}
// tipo_disparo e coluna dedicada (preenchida pelos fluxos 6.01 e 7.01);
// payload.template fica como fallback para eventos antigos.
function templateDoEvento(e) {
  return e.tipo_disparo || parsePayload(e.payload).template || null;
}
function canalPorApp(app) {
  const a = String(app || '').toUpperCase();
  if (a.indexOf('INBOUND') >= 0) return 'inbound';
  if (a.indexOf('REMARKETING') >= 0) return 'remarketing';
  if (a.indexOf('OUTBOUND') >= 0) return 'outbound';
  return null;
}
function canalPorTemplate(tpl) {
  const t = String(tpl || '');
  if (t.indexOf('inbound') >= 0) return 'inbound';
  if (t.indexOf('outbound') >= 0) return 'outbound';
  if (/^mensagem_\d+/.test(t)) return 'remarketing';
  return null;
}
// Tentativa dentro da regua de remarketing (1, 2 ou 3). Disparo inicial
// de inbound/outbound nao tem regua -> 'inicial'.
function tentativaDoTemplate(tpl) {
  const t = String(tpl || '');
  if (/disparo_inicial/.test(t)) return 'inicial';
  const m = t.match(/mensagem_(\d+)/);
  return m ? m[1] : null;
}
// Chave do lead: mailing_id quando existe, senao os ultimos 11 digitos do
// telefone. Sem isso, todo evento sem mailing_id colapsava num unico
// balde (bug do report antigo).
function chaveLead(e) {
  if (e.mailing_id !== null && e.mailing_id !== undefined && e.mailing_id !== '') return 'm' + e.mailing_id;
  const tel = String(e.telefone || '').replace(/\D/g, '');
  return tel ? 't' + tel.slice(-11) : null;
}

const CANAIS = ['inbound', 'remarketing', 'outbound', 'parcerias', 'outros'];
function novoBalde() {
  return {
    disparos_ontem: 0, disparos_semana: 0,
    disparos_ontem_t: { inicial: 0, '1': 0, '2': 0, '3': 0 },
    disparos_semana_t: { inicial: 0, '1': 0, '2': 0, '3': 0 },
    falhas_ontem: 0, falhas_semana: 0,
    respostas_ontem: 0, respostas_semana: 0,
    respostas_ontem_t: { inicial: 0, '1': 0, '2': 0, '3': 0, sem_disparo: 0 },
    respostas_semana_t: { inicial: 0, '1': 0, '2': 0, '3': 0, sem_disparo: 0 },
    enc_advisor_ontem: 0, enc_advisor_semana: 0,
    enc_parcerias_ontem: 0, enc_parcerias_semana: 0,
    calls_marcadas_ontem: 0, calls_marcadas_semana: 0,
    calls_realizadas_ontem: 0, calls_realizadas_semana: 0,
    calls_noshow_ontem: 0, calls_noshow_semana: 0,
    calls_hoje: 0, calls_a_frente: 0
  };
}
const R = {};
for (const c of CANAIS) R[c] = novoBalde();

// ---------------------------------------------------------------------
// 2. Historico de disparos por lead (canal + tentativa + data)
// ---------------------------------------------------------------------
const historico = {};   // chaveLead -> [{ts, canal, tentativa}]
for (const e of eventos) {
  if (e.tipo_evento !== 'disparo_enviado') continue;
  const k = chaveLead(e);
  const ts = tsLocal(e.created_at);
  if (!k || ts === null) continue;
  const tpl = templateDoEvento(e);
  const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
  (historico[k] = historico[k] || []).push({ ts, canal, tentativa: tentativaDoTemplate(tpl) });
}
for (const k in historico) historico[k].sort((a, b) => a.ts - b.ts);

// Canal do lead num INSTANTE: o ultimo disparo ate aquela data. Usar o
// "ultimo disparo de todos" jogaria para remarketing uma call que nasceu da
// conversa de inbound semanas antes de o lead entrar no FUP.
function canalDoLeadEm(k, ts) {
  const h = historico[k];
  if (!h || !h.length) return null;
  let canal = null;
  for (const d of h) { if (d.ts <= ts) canal = d.canal; else break; }
  return canal || h[0].canal;
}
function canalDoLead(k) {
  const h = historico[k];
  return h && h.length ? h[h.length - 1].canal : null;
}
// Ultimo disparo ANTES da resposta. Janela de 7 dias para atribuir a
// tentativa: resposta a um disparo de 3 meses atras nao e resposta
// daquele disparo (o report antigo atribuia sem limite nenhum).
const JANELA_ATRIB_MS = 7 * DIA_MS;
function disparoAnterior(k, ts) {
  const h = historico[k];
  if (!h) return null;
  let achado = null;
  for (const d of h) { if (d.ts <= ts) achado = d; else break; }
  if (!achado) return null;
  return { canal: achado.canal, tentativa: (ts - achado.ts) <= JANELA_ATRIB_MS ? achado.tentativa : null };
}

// ---------------------------------------------------------------------
// 3. Disparos, falhas, respostas e encaminhamentos
// ---------------------------------------------------------------------
const vistoRespOntem = new Set();
const vistoRespSemana = new Set();

for (const e of eventos) {
  const dia = diaLocal(e.created_at);
  if (dia === null) continue;
  const ontem = ehOntem(dia);
  const semana = ehSemana(dia);
  if (!ontem && !semana) continue;

  const k = chaveLead(e);
  const tipo = String(e.tipo_evento || '');

  if (tipo === 'disparo_enviado') {
    const tpl = templateDoEvento(e);
    const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
    const t = tentativaDoTemplate(tpl);
    const b = R[canal] || R.outros;
    if (ontem) { b.disparos_ontem++; if (t) b.disparos_ontem_t[t] = (b.disparos_ontem_t[t] || 0) + 1; }
    if (semana) { b.disparos_semana++; if (t) b.disparos_semana_t[t] = (b.disparos_semana_t[t] || 0) + 1; }

  } else if (tipo === 'disparo_falhou') {
    const tpl = templateDoEvento(e);
    const canal = canalPorApp(e.nome_app) || canalPorTemplate(tpl) || 'outros';
    const b = R[canal] || R.outros;
    if (ontem) b.falhas_ontem++;
    if (semana) b.falhas_semana++;

  } else if (tipo === 'resposta_recebida') {
    const ts = tsLocal(e.created_at);
    const ant = k ? disparoAnterior(k, ts) : null;
    // O nome_app da resposta vem do historico de mensagens (trigger
    // fn_sdr_detecta_resposta) = o agente que recebeu. E a fonte certa.
    const canal = canalPorApp(e.nome_app) || (ant && ant.canal) || 'outros';
    const tent = ant && ant.tentativa ? ant.tentativa : 'sem_disparo';
    const b = R[canal] || R.outros;
    // dedupe: mesmo lead, mesmo dia = 1 resposta
    const chave = (k || 'evt' + e.id) + '_' + dia;
    if (ontem && !vistoRespOntem.has(chave)) {
      vistoRespOntem.add(chave);
      b.respostas_ontem++;
      b.respostas_ontem_t[tent] = (b.respostas_ontem_t[tent] || 0) + 1;
    }
    if (semana && !vistoRespSemana.has(chave)) {
      vistoRespSemana.add(chave);
      b.respostas_semana++;
      b.respostas_semana_t[tent] = (b.respostas_semana_t[tent] || 0) + 1;
    }

  } else if (/encaminh/i.test(tipo)) {
    // Eventos 'encaminhado_advisor' / 'encaminhado_parcerias', gravados pela
    // 6.04 (remarketing) e 7.04 (inbound), ja com nome_app fixo do fluxo.
    const p = parsePayload(e.payload);
    const destinoRaw = String(p.destino || tipo).toLowerCase();
    const destino = /parceri/.test(destinoRaw) ? 'parcerias' : (/advisor/.test(destinoRaw) ? 'advisor' : null);
    if (!destino) continue;
    const canal = canalPorApp(e.nome_app) || (k && canalDoLead(k)) || 'outros';
    const b = R[canal] || R.outros;
    const campo = destino === 'advisor' ? 'enc_advisor' : 'enc_parcerias';
    if (ontem) b[campo + '_ontem']++;
    if (semana) b[campo + '_semana']++;
  }
}

// ---------------------------------------------------------------------
// 4. Calls (node "agenda", linha a linha) atribuidas ao canal de ORIGEM
// ---------------------------------------------------------------------
const MIDIA_CANAL = { '14': 'inbound', '15': 'remarketing', '5': 'remarketing', '2': 'parcerias', '1': 'outbound', '4': 'outbound' };

// --- Reunioes carimbadas pelos calendars (sdr_reunioes.origem) ---
// Fonte mais confiavel de canal para uma call: quem agendou disse quem era.
// So cobre o que a IA agendou; call marcada na mao no CRM cai nos fallbacks.
const reunioesPorLead = {};
for (const r of $('Reunioes SDR - Ler').all().map(i => i.json)) {
  const canal = canalPorApp(r.origem);
  if (!canal) continue;
  const chaves = [];
  if (r.mailing_id) chaves.push('m' + r.mailing_id);
  const tel = String(r.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  const marcos = [tsLocal(r.criado_em), tsLocal(r.data_hora_agendada)].filter(t => t !== null);
  for (const c of chaves) (reunioesPorLead[c] = reunioesPorLead[c] || []).push({ canal, marcos });
}
function canalPorReuniao(chaves, ts) {
  let melhor = null, menorDist = Infinity;
  for (const c of chaves) {
    for (const r of (reunioesPorLead[c] || [])) {
      for (const m of r.marcos) {
        const dist = Math.abs(m - ts);
        if (dist < menorDist) { menorDist = dist; melhor = r.canal; }
      }
    }
  }
  return melhor;
}

function canalDaCall(row, ts) {
  const chaves = [];
  if (row.mailing_id !== null && row.mailing_id !== undefined && row.mailing_id !== '') chaves.push('m' + row.mailing_id);
  const tel = String(row.telefone || '').replace(/\D/g, '');
  if (tel) chaves.push('t' + tel.slice(-11));
  return canalPorReuniao(chaves, ts)
      || (chaves.length ? canalDoLeadEm(chaves[0], ts) : null)
      || MIDIA_CANAL[String(row.midia)]
      || 'outros';
}

const linhasAgenda = $('agenda1').all().map(i => i.json).filter(r => r && r.evento);
for (const row of linhasAgenda) {
  const dia = row.dia ? diaLocal(String(row.dia).slice(0, 10) + 'T12:00:00Z') : null;
  const b = R[canalDaCall(row, dia !== null ? dia : Date.now())] || R.outros;
  const ontem = dia !== null && ehOntem(dia);
  const semana = dia !== null && ehSemana(dia);
  switch (row.evento) {
    case 'marcada':
      if (ontem) b.calls_marcadas_ontem++;
      if (semana) b.calls_marcadas_semana++;
      break;
    case 'realizada':
      if (ontem) b.calls_realizadas_ontem++;
      if (semana) b.calls_realizadas_semana++;
      break;
    case 'no_show':
      if (ontem) b.calls_noshow_ontem++;
      if (semana) b.calls_noshow_semana++;
      break;
    case 'agendada_hoje': b.calls_hoje++; break;
    case 'agendada_frente': b.calls_a_frente++; break;
  }
}

// ---------------------------------------------------------------------
// 5. Montagem das mensagens
// ---------------------------------------------------------------------
const periodo = `Ontem ${ddmm(ONTEM)} · semana ${ddmm(INICIO_SEMANA)} → ${ddmm(ONTEM)}`;

// A soma das tentativas tem que fechar com o total. Disparo antigo, sem
// tipo_disparo e sem template no payload, nao cai em nenhuma tentativa -
// em vez de sumir da conta, aparece como "sem template".
// A soma das etapas tem que fechar com o total. "entrada" e o primeiro
// contato da regua (template disparo_inicial_*, disparado pela fila de
// entrada do 6.01) - nao e 1a/2a/3a tentativa. Se ainda sobrar diferenca,
// e disparo sem template identificavel e aparece como tal, em vez de sumir.
function entradaLbl(t) {
  return (t.inicial || 0) > 0 ? `entrada: ${t.inicial} | ` : '';
}
function restoDisp(total, t) {
  const resto = total - ((t['1'] || 0) + (t['2'] || 0) + (t['3'] || 0) + (t.inicial || 0));
  return resto > 0 ? ` | sem template: ${resto}` : '';
}

function blocoEncaminhamentos(b) {
  return `➡️ *ENCAMINHAMENTOS*
Advisor — ontem: ${b.enc_advisor_ontem} | semana: ${b.enc_advisor_semana}
Parcerias — ontem: ${b.enc_parcerias_ontem} | semana: ${b.enc_parcerias_semana}`;
}
function blocoCalls(b) {
  return `📅 *CALLS*
Agendadas — ontem: ${b.calls_marcadas_ontem} | semana: ${b.calls_marcadas_semana}
Realizadas — ontem: ${b.calls_realizadas_ontem} | semana: ${b.calls_realizadas_semana}
No-show — ontem: ${b.calls_noshow_ontem} | semana: ${b.calls_noshow_semana}
Na agenda — hoje: ${b.calls_hoje} | daqui pra frente: ${b.calls_a_frente}`;
}

// ---- INBOUND ----
const i = R.inbound;
const mensagem_inbound = `*REPORT INBOUND*
_${periodo}_

📤 *DISPAROS*
Ontem: ${i.disparos_ontem}${i.falhas_ontem ? ` (falhas: ${i.falhas_ontem})` : ''}
Semana: ${i.disparos_semana}${i.falhas_semana ? ` (falhas: ${i.falhas_semana})` : ''}

💬 *RESPOSTAS* (leads distintos que responderam)
Ontem: ${i.respostas_ontem} — ${taxa(i.respostas_ontem, i.disparos_ontem)}
Semana: ${i.respostas_semana} — ${taxa(i.respostas_semana, i.disparos_semana)}

${blocoEncaminhamentos(i)}

${blocoCalls(i)}`;

// ---- REMARKETING ----
const r = R.remarketing;
const dOnt = r.disparos_ontem_t, dSem = r.disparos_semana_t;
const rOnt = r.respostas_ontem_t, rSem = r.respostas_semana_t;
const o = R.outbound, p = R.parcerias, x = R.outros;
const outrosDispOntem = o.disparos_ontem + p.disparos_ontem + x.disparos_ontem;
const outrosDispSemana = o.disparos_semana + p.disparos_semana + x.disparos_semana;
const totalDispOntem = i.disparos_ontem + r.disparos_ontem + outrosDispOntem;
const totalDispSemana = i.disparos_semana + r.disparos_semana + outrosDispSemana;
const totalRespOntem = CANAIS.reduce((s, c) => s + R[c].respostas_ontem, 0);
const totalRespSemana = CANAIS.reduce((s, c) => s + R[c].respostas_semana, 0);

const mensagem_remarketing = `*REPORT REMARKETING*
_${periodo}_

📤 *DISPAROS*
Ontem: ${r.disparos_ontem}${r.falhas_ontem ? ` (falhas: ${r.falhas_ontem})` : ''}
• ${entradaLbl(dOnt)}1ª: ${dOnt['1']} | 2ª: ${dOnt['2']} | 3ª: ${dOnt['3']}${restoDisp(r.disparos_ontem, dOnt)}
Semana: ${r.disparos_semana}${r.falhas_semana ? ` (falhas: ${r.falhas_semana})` : ''}
• ${entradaLbl(dSem)}1ª: ${dSem['1']} | 2ª: ${dSem['2']} | 3ª: ${dSem['3']}${restoDisp(r.disparos_semana, dSem)}

💬 *RESPOSTAS* (leads distintos que responderam)
Ontem: ${r.respostas_ontem} — ${taxa(r.respostas_ontem, r.disparos_ontem)}
• ${entradaLbl(rOnt)}1ª: ${rOnt['1']} | 2ª: ${rOnt['2']} | 3ª: ${rOnt['3']} | sem disparo recente: ${rOnt.sem_disparo}
Semana: ${r.respostas_semana} — ${taxa(r.respostas_semana, r.disparos_semana)}
• ${entradaLbl(rSem)}1ª: ${rSem['1']} | 2ª: ${rSem['2']} | 3ª: ${rSem['3']} | sem disparo recente: ${rSem.sem_disparo}

${blocoEncaminhamentos(r)}

${blocoCalls(r)}

—
*TOTAL DA OPERAÇÃO (todos os canais)*
Disparos — ontem: ${totalDispOntem} | semana: ${totalDispSemana}
Respostas — ontem: ${totalRespOntem} | semana: ${totalRespSemana}
Outros canais (outbound/parcerias) — disparos ontem: ${outrosDispOntem} | semana: ${outrosDispSemana}
Respostas sem canal identificado — ontem: ${x.respostas_ontem} | semana: ${x.respostas_semana}
Calls agendadas ontem — inbound: ${i.calls_marcadas_ontem} | remarketing: ${r.calls_marcadas_ontem} | parcerias: ${p.calls_marcadas_ontem} | outros: ${o.calls_marcadas_ontem + x.calls_marcadas_ontem}`;

return [{
  json: {
    referencia_ontem: ddmm(ONTEM),
    inicio_semana: ddmm(INICIO_SEMANA),
    mensagem_inbound,
    mensagem_remarketing,
    detalhe: R
  }
}];
